#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=8

cd "$(dirname "$0")/.."
REPO_ROOT=$PWD
APP_DOMAIN="app.gymbutler.cavender.dev"
APP_URL="https://$APP_DOMAIN"
LOCAL_URL="http://localhost:3001"
VERCEL="bunx vercel@65"
# Local dev values for the web app land here; nothing secret is written.
ENV_FILE="$REPO_ROOT/apps/web/.env"

banner "GymButler: Convex + Vercel deploy setup"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Convex: log in and create the project"
say "This logs you in to Convex, creates the project and your dev deployment,"
say "and pushes the functions once. It writes packages/backend/.env.local."
step "When asked, choose to create a new project and name it 'gymbutler'."
pause "Press Enter to run 'bun run dev:setup'…"
(cd packages/backend && bun run dev:setup)
[[ -f packages/backend/.env.local ]] || { warn "packages/backend/.env.local not found; re-run this stage."; exit 1; }
say ""
say "Copying the dev deployment URLs into apps/web/.env for local dev:"
for key in VITE_CONVEX_URL VITE_CONVEX_SITE_URL; do
  value=$(ENV_FILE=packages/backend/.env.local _existing "$key" || true)
  if [[ -n "$value" ]]; then write_env "$key" "$value"
  else SKIPPED+=("$key missing from packages/backend/.env.local; copy it to apps/web/.env"); warn "$key not found"; fi
done
pause

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Convex: auth settings for your dev deployment"
say "Better Auth needs SITE_URL (where the web app runs) and a random"
say "BETTER_AUTH_SECRET on each deployment. Setting them on dev now:"
note "SITE_URL=$LOCAL_URL"
if confirm "Set these on the dev deployment (overwrites existing values)?"; then
  (cd packages/backend &&
    bunx convex env set SITE_URL "$LOCAL_URL" &&
    bunx convex env set BETTER_AUTH_SECRET "$(openssl rand -base64 32)")
else
  SKIPPED+=("dev SITE_URL / BETTER_AUTH_SECRET (bunx convex env set …, in packages/backend)")
fi
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Convex: auth settings for production"
say "Same two values on the production deployment, with its own secret."
note "SITE_URL=$APP_URL"
warn "Replacing BETTER_AUTH_SECRET on production signs everyone out."
if confirm "Set these on the production deployment?"; then
  (cd packages/backend &&
    bunx convex env set --prod SITE_URL "$APP_URL" &&
    bunx convex env set --prod BETTER_AUTH_SECRET "$(openssl rand -base64 32)")
else
  SKIPPED+=("prod SITE_URL / BETTER_AUTH_SECRET (bunx convex env set --prod …, in packages/backend)")
fi
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Convex: production deploy key"
say "CI uses this key to deploy functions to production."
open_url "https://dashboard.convex.dev"
step "Open the 'gymbutler' project, then switch to the Production deployment."
step "Go to Settings → URL & Deploy Key → Generate Production Deploy Key."
step "Copy the key (it starts with 'prod:')."
ask_secret CONVEX_DEPLOY_KEY "Paste the production deploy key:"
[[ "$CONVEX_DEPLOY_KEY" == prod:* ]] || warn "That doesn't start with 'prod:'; double-check it's the production key."
set_secret CONVEX_DEPLOY_KEY "$CONVEX_DEPLOY_KEY"
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Vercel: log in and create the project"
say "This logs in to Vercel and links this repo to a new 'gymbutler' project."
step "Pick the team that owns cavender.dev (the one hosting simpledex)."
step "Create a new project named 'gymbutler'; accept the default directory (./)."
note "If asked to connect the Git repo, either answer is fine: vercel.json turns"
note "off Vercel's own Git deploys, so only the GitHub workflow deploys."
pause "Press Enter to run 'vercel login' then 'vercel link'…"
$VERCEL login
$VERCEL link --project gymbutler
[[ -f .vercel/project.json ]] || { warn ".vercel/project.json not found; re-run this stage."; exit 1; }
VERCEL_ORG_ID=$(sed -n 's/.*"orgId": *"\([^"]*\)".*/\1/p' .vercel/project.json)
VERCEL_PROJECT_ID=$(sed -n 's/.*"projectId": *"\([^"]*\)".*/\1/p' .vercel/project.json)
set_secret VERCEL_ORG_ID "$VERCEL_ORG_ID"
set_secret VERCEL_PROJECT_ID "$VERCEL_PROJECT_ID"
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Vercel: access token for CI"
open_url "https://vercel.com/account/tokens"
step "Create a token named 'gymbutler GitHub Actions'."
step "Scope it to the same team as the project; pick an expiration you'll remember."
step "Copy the token (it's only shown once)."
ask_secret VERCEL_TOKEN "Paste the Vercel token:"
set_secret VERCEL_TOKEN "$VERCEL_TOKEN"
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Vercel: custom domain"
say "Point $APP_DOMAIN at the project."
open_url "https://vercel.com/dashboard"
step "Open the 'gymbutler' project → Settings → Domains."
step "Add $APP_DOMAIN."
note "cavender.dev already uses Vercel DNS, so it should verify on its own."
note "If Vercel shows a DNS record to add instead, add it where cavender.dev's DNS lives."
pause "Press Enter once the domain is added…"

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Turn on deploys"
say "Sets the DEPLOY_ENABLED repo variable. From then on, every push to master"
say "that passes CI deploys Convex and then the web app."
if confirm "Enable deploys?"; then
  set_var DEPLOY_ENABLED true
  if confirm "Run the first deploy now from master?"; then
    gh workflow run ci.yml --ref master
    sleep 5
    note "Watching the run (Ctrl-C stops watching, not the deploy):"
    run_id=$(gh run list --workflow ci.yml --branch master --limit 1 --json databaseId --jq '.[0].databaseId')
    if ! gh run watch "$run_id" --exit-status; then
      warn "The run didn't succeed; check: gh run view $run_id --log-failed"
    fi
  fi
else
  SKIPPED+=("enable deploys: gh variable set DEPLOY_ENABLED --body true")
fi
pause

finish
note "Live at $APP_URL once the first deploy finishes."
note "Local dev: bun run dev"
}

run_wizard "$@"; exit
